package com.mg.whiffletreeaero;

import android.app.*;
import android.os.Bundle;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;

public class MainActivity extends Activity {
  final int NAVY=Color.rgb(8,22,38),PANEL=Color.rgb(17,38,58),BLUE=Color.rgb(44,120,235),CYAN=Color.rgb(45,200,220),ORANGE=Color.rgb(245,160,40),GREEN=Color.rgb(55,190,105),YELLOW=Color.rgb(250,205,70);
  LinearLayout root,wizard; DynamicRigView rig; TextView status,result,stepTitle,help; Spinner qProfile; EditText L,F,M,stations,layers,actCount,actCapacity,pressure,sf,padW,padL; Button calc,auto; int step=0;
  String[] Q={"Elliptic","Uniform","Triangular root-high","Triangular tip-high","Parabolic"};
  String[] ST={"1/6 Problem","2/6 Stations + q(x)","3/6 Whiffletree layers","4/6 Actuator count","5/6 Hardware defaults","6/6 Verify"};
  String[] H={"Hedef toplam kuvvet ve momenti gir. Varsayılan değerler EFT +Z bending eğitim örneğidir.","Station sayısı ve q(x) profili seçildiğinde Fi kuvvetleri otomatik hesaplanır.","Layer 1, 2 veya 3 seç. Görsel ağaç seçilen katman kadar dallanır.","Actuator sayısını değiştir. Aktüatörler tank boyunca yeniden yerleşir ve ilgili station gruplarına bağlanır.","Basınç, safety factor, actuator kapasitesi ve load-pad ölçülerini kontrol et.","ΣF/ΣM, actuator yükleri ve her beam'in taşıdığı kuvveti kontrol et."};

  @Override public void onCreate(Bundle b){super.onCreate(b);
    ScrollView sv=new ScrollView(this); root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(10),dp(10),dp(10),dp(28));root.setBackgroundColor(NAVY);sv.addView(root);
    root.addView(tx("EFT WHIFFLETREE SMART DESIGNER",24,true,Color.WHITE));root.addView(tx("v1.4 • Dynamic actuator topology • Dynamic 1/2/3-layer tree",12,false,Color.rgb(180,205,225)));
    status=card("Hazır",Color.rgb(13,45,68));root.addView(status,lp());
    rig=new DynamicRigView();root.addView(rig,new LinearLayout.LayoutParams(-1,dp(520)));
    wizard=new LinearLayout(this);wizard.setOrientation(LinearLayout.VERTICAL);wizard.setPadding(dp(10),dp(10),dp(10),dp(10));wizard.setBackground(bg(PANEL,12));root.addView(wizard,lp());
    stepTitle=tx("",18,true,Color.WHITE);help=tx("",13,false,Color.rgb(190,215,232));wizard.addView(stepTitle);wizard.addView(help);
    F=field("Target total load [kN]","305.7");M=field("Target moment [kN·m]","1280");L=field("Tank length [m]","7.6");stations=field("Station count","12");
    TextView ql=tx("q(x) profile",12,true,Color.rgb(185,210,230));wizard.addView(ql);qProfile=new Spinner(this);qProfile.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,Q));wizard.addView(qProfile,lp());
    layers=field("Whiffletree layer count (1-3)","3");actCount=field("Actuator count (1-8)","4");actCapacity=field("Actuator nominal capacity [kN]","120");pressure=field("Hydraulic pressure [bar]","210");sf=field("Sizing factor","1.50");padW=field("Pad width [mm]","150");padL=field("Pad length [mm]","250");
    auto=new Button(this);auto.setText("AUTO OPTIMIZE ACTUATORS");auto.setOnClickListener(v->{try{Calc c=compute(true);actCount.setText(String.valueOf(c.nAct));preview(c);result.setText("Auto actuator count = "+c.nAct+"\nTopology and tree updated.");}catch(Exception e){result.setText("Girişleri kontrol et.");}});wizard.addView(auto,lp());
    calc=new Button(this);calc.setText("HESAPLA + GÖRSELİ GÜNCELLE");calc.setOnClickListener(v->calculate());wizard.addView(calc,lp());
    LinearLayout nav=new LinearLayout(this);Button prev=new Button(this),next=new Button(this);prev.setText("← Geri");next.setText("Devam →");nav.addView(prev,new LinearLayout.LayoutParams(0,dp(48),1));nav.addView(next,new LinearLayout.LayoutParams(0,dp(48),1));wizard.addView(nav,lp());
    prev.setOnClickListener(v->{if(step>0){step--;render();}});next.setOnClickListener(v->{if(step<5){step++;render();}else calculate();});
    qProfile.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?>p,View v,int pos,long id){safe();}public void onNothingSelected(android.widget.AdapterView<?>p){}});
    result=card("Layer ve actuator sayılarını değiştirince tank altındaki ağaç ve actuator yerleşimi otomatik güncellenecek.",Color.rgb(12,34,52));root.addView(result,lp());
    root.addView(card("Ön tasarım/eğitim aracıdır. Nihai test rig'i için onaylı load report, FEM, üretici limitleri ve test prosedürü gerekir.",Color.rgb(63,45,12)),lp());
    TextWatcher tw=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){safe();}public void afterTextChanged(Editable e){}};
    for(EditText e:new EditText[]{F,M,L,stations,layers,actCount,actCapacity,pressure,sf,padW,padL})e.addTextChangedListener(tw);
    setContentView(sv);render();safe();
  }

  EditText field(String label,String def){wizard.addView(tx(label,12,true,Color.rgb(185,210,230)));EditText e=new EditText(this);e.setText(def);e.setTextColor(Color.WHITE);e.setSingleLine(true);e.setTextSize(16);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);e.setBackground(bg(Color.rgb(25,52,75),8));e.setPadding(dp(10),0,dp(10),0);wizard.addView(e,new LinearLayout.LayoutParams(-1,dp(44)));return e;}
  void render(){stepTitle.setText(ST[step]);help.setText(H[step]);show(F,step==0||step==4);show(M,step==0||step==4);show(L,step==0);show(stations,step==1);qProfile.setVisibility(step==1?View.VISIBLE:View.GONE);show(layers,step==2);show(actCount,step==3);show(actCapacity,step==3||step==4);show(pressure,step==4);show(sf,step==4);show(padW,step==4);show(padL,step==4);auto.setVisibility(step==3?View.VISIBLE:View.GONE);calc.setVisibility(step==5?View.VISIBLE:View.GONE);safe();}
  void show(EditText e,boolean on){int i=wizard.indexOfChild(e);if(i>0)wizard.getChildAt(i-1).setVisibility(on?View.VISIBLE:View.GONE);e.setVisibility(on?View.VISIBLE:View.GONE);}
  void safe(){try{preview(compute(false));}catch(Exception ignored){}}
  void preview(Calc c){rig.set(c);status.setText(String.format(Locale.US,"ΣF %.1f kN • M %.1f kN·m • %d stations • %d layers • %d actuators",c.sumF,c.calcM,c.n,c.layers,c.nAct));}
  void calculate(){try{Calc c=compute(false);preview(c);StringBuilder s=new StringBuilder();s.append("DYNAMIC TOPOLOGY RESULT\n\n");s.append(String.format(Locale.US,"Stations: %d\nLayers: %d\nActuators: %d\nΣF %.1f kN\nM %.1f kN·m\nMoment error %.2f %%\n\n",c.n,c.layers,c.nAct,c.sumF,c.calcM,c.mErr));s.append(String.format(Locale.US,"Design load %.1f kN\nLoad/actuator %.1f kN\nEquivalent piston bore %.1f mm @ %.0f bar\nLoad-cell preselect ≥ %.0f kN\n\n",c.designF,c.actLoad,c.bore,c.pbar,c.lc));s.append("TREE\n").append(c.tree);result.setText(s.toString());}catch(Exception e){result.setText("Geçersiz giriş.");}}

  Calc compute(boolean optimize){Calc c=new Calc();c.L=d(L);c.targetF=Math.abs(d(F));c.targetM=d(M);c.n=clamp((int)Math.round(d(stations)),4,16);c.layers=clamp((int)Math.round(d(layers)),1,3);double cap=Math.max(1,d(actCapacity));c.pbar=Math.max(1,d(pressure));c.sf=Math.max(1,d(sf));c.designF=c.targetF*c.sf;int manual=clamp((int)Math.round(d(actCount)),1,8);int minCap=(int)Math.ceil(c.designF/cap);int minTopo=Math.max(1,(int)Math.ceil(c.n/Math.pow(2,c.layers)));c.nAct=optimize?clamp(Math.max(minCap,minTopo),1,8):manual;c.actLoad=c.designF/c.nAct;c.bore=Math.sqrt(4*(c.actLoad*1000)/(c.pbar*100000)/Math.PI)*1000;c.lc=std(c.actLoad*1.2);
    c.x=new double[c.n];c.fi=new double[c.n];double[] w=new double[c.n];double sw=0;int q=qProfile.getSelectedItemPosition();for(int i=0;i<c.n;i++){double u=(i+.5)/c.n;c.x[i]=u*c.L;if(q==0)w[i]=Math.sqrt(Math.max(0,1-Math.pow(2*u-1,2)))+.05;else if(q==1)w[i]=1;else if(q==2)w[i]=1.15-u;else if(q==3)w[i]=.15+u;else w[i]=.25+4*u*(1-u);sw+=w[i];}for(int i=0;i<c.n;i++)c.fi[i]=c.targetF*w[i]/sw;
    double desired=Math.abs(c.targetM),base=0;for(int i=0;i<c.n;i++)base+=c.fi[i]*c.x[i];double mean=0;for(double xx:c.x)mean+=xx;mean/=c.n;double den=0;for(double xx:c.x)den+=(xx-mean)*(xx-mean);double delta=desired-base;if(Math.abs(delta)>1e-9&&den>1e-9)for(int i=0;i<c.n;i++)c.fi[i]+=delta*(c.x[i]-mean)/den;
    boolean neg=false;for(double v:c.fi)if(v<0)neg=true;if(neg){for(int i=0;i<c.n;i++)c.fi[i]=Math.max(.001,c.fi[i]);double ss=0;for(double v:c.fi)ss+=v;for(int i=0;i<c.n;i++)c.fi[i]*=c.targetF/ss;}
    c.sumF=0;c.calcM=0;for(int i=0;i<c.n;i++){c.sumF+=c.fi[i];c.calcM+=c.fi[i]*c.x[i];}if(c.targetM<0)c.calcM=-c.calcM;c.mErr=Math.abs(c.targetM)>1e-6?100*(c.calcM-c.targetM)/Math.abs(c.targetM):0;c.tree=synth(c);return c;}

  String synth(Calc c){StringBuilder sb=new StringBuilder();ArrayList<Double> vals=new ArrayList<>();for(double f:c.fi)vals.add(f*c.sf);for(int lev=1;lev<=c.layers&&vals.size()>1;lev++){ArrayList<Double> nx=new ArrayList<>();sb.append("Layer ").append(lev).append(":\n");for(int i=0;i<vals.size();i+=2){if(i+1<vals.size()){double a=vals.get(i),b=vals.get(i+1),sum=a+b;sb.append(String.format(Locale.US," B%d: %.1f + %.1f = %.1f kN | pivot %.0f/%.0f %%\n",i/2+1,a,b,sum,100*b/sum,100*a/sum));nx.add(sum);}else{nx.add(vals.get(i));sb.append(String.format(Locale.US," B%d: single %.1f kN\n",i/2+1,vals.get(i)));}}vals=nx;}sb.append("Top branches: ").append(vals.size()).append("\nActuators: ").append(c.nAct).append("\n");return sb.toString();}

  class DynamicRigView extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG),t=new Paint(Paint.ANTI_ALIAS_FLAG);Calc c;DynamicRigView(){super(MainActivity.this);setBackgroundColor(Color.rgb(5,17,29));t.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));}void set(Calc x){c=x;invalidate();}
    protected void onDraw(Canvas cn){super.onDraw(cn);if(c==null)return;int w=getWidth(),h=getHeight();float left=w*.06f,right=w*.95f,len=right-left;float tankY=h*.26f;
      t.setColor(Color.WHITE);t.setTextSize(dp(12));cn.drawText("EFT + dynamic whiffletree topology",dp(10),dp(20),t);t.setTextSize(dp(10));cn.drawText("Layers="+c.layers+"  Actuators="+c.nAct,dp(10),dp(38),t);
      p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(45,57,72));RectF tank=new RectF(left,tankY-dp(22),right,tankY+dp(22));cn.drawRoundRect(tank,dp(22),dp(22),p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(Color.LTGRAY);cn.drawRoundRect(tank,dp(22),dp(22),p);
      float[] sx=new float[c.n];for(int i=0;i<c.n;i++){sx[i]=left+(float)(c.x[i]/c.L)*len;p.setColor(CYAN);p.setStrokeWidth(2);cn.drawLine(sx[i],tankY-dp(22),sx[i],tankY+dp(22),p);float arrow=dp(26)+(float)Math.min(dp(50),c.fi[i]*.55);p.setColor(BLUE);p.setStrokeWidth(4);cn.drawLine(sx[i],tankY-dp(25),sx[i],tankY-dp(25)-arrow,p);cn.drawText("S"+(i+1),sx[i]-dp(7),tankY+dp(38),t);}
      ArrayList<float[]> nodes=new ArrayList<>();for(int i=0;i<c.n;i++)nodes.add(new float[]{sx[i],tankY+dp(30),(float)(c.fi[i]*c.sf)});
      float baseY=tankY+dp(70);int level=1;while(level<=c.layers&&nodes.size()>1){ArrayList<float[]> next=new ArrayList<>();float y=baseY+dp(55)*(level-1);p.setColor(level==1?ORANGE:(level==2?YELLOW:CYAN));p.setStrokeWidth(5);for(int i=0;i<nodes.size();i+=2){if(i+1<nodes.size()){float[] a=nodes.get(i),b=nodes.get(i+1);float sum=a[2]+b[2];float px=(a[0]*b[2]+b[0]*a[2])/sum;cn.drawLine(a[0],y,b[0],y,p);p.setStrokeWidth(2);cn.drawLine(a[0],a[1],a[0],y,p);cn.drawLine(b[0],b[1],b[0],y,p);p.setStyle(Paint.Style.FILL);cn.drawCircle(px,y,dp(4),p);p.setStyle(Paint.Style.STROKE);t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText(String.format(Locale.US,"%.0f kN",sum),px-dp(17),y-dp(7),t);next.add(new float[]{px,y,sum});}else next.add(nodes.get(i));}nodes=next;level++;}
      float actuatorY=Math.min(h-dp(65),baseY+dp(55)*c.layers+dp(20));p.setStrokeWidth(2);for(int a=0;a<c.nAct;a++){int start=(int)Math.floor((double)a*nodes.size()/c.nAct);int end=(int)Math.floor((double)(a+1)*nodes.size()/c.nAct)-1;if(start>=nodes.size())start=nodes.size()-1;if(end<start)end=start;if(end>=nodes.size())end=nodes.size()-1;float center=0,total=0;for(int j=start;j<=end;j++){center+=nodes.get(j)[0]*nodes.get(j)[2];total+=nodes.get(j)[2];}if(total>0)center/=total;else center=w*(a+1f)/(c.nAct+1f);p.setColor(GREEN);p.setStyle(Paint.Style.FILL);cn.drawRoundRect(new RectF(center-dp(14),actuatorY-dp(32),center+dp(14),actuatorY+dp(5)),dp(6),dp(6),p);p.setStyle(Paint.Style.STROKE);p.setColor(Color.WHITE);for(int j=start;j<=end;j++)cn.drawLine(center,actuatorY-dp(32),nodes.get(j)[0],nodes.get(j)[1],p);t.setTextSize(dp(9));cn.drawText("A"+(a+1),center-dp(7),actuatorY+dp(18),t);cn.drawText(String.format(Locale.US,"%.0f",c.actLoad),center-dp(9),actuatorY+dp(31),t);}p.setColor(Color.rgb(80,95,110));p.setStrokeWidth(7);cn.drawLine(left,actuatorY+dp(38),right,actuatorY+dp(38),p);
    }}

  static class Calc{double L,targetF,targetM,pbar,sf,designF,actLoad,bore,lc,sumF,calcM,mErr;int n,layers,nAct;double[]x,fi;String tree;}
  double std(double v){double[]a={10,20,25,50,75,100,150,200,250,300,500,750,1000};for(double x:a)if(x>=v)return x;return Math.ceil(v/100)*100;}double d(EditText e){return Double.parseDouble(e.getText().toString().trim().replace(',','.'));}int clamp(int v,int a,int b){return Math.max(a,Math.min(b,v));}int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}LinearLayout.LayoutParams lp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));return p;}TextView tx(String s,int z,boolean b,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(Typeface.DEFAULT,b?Typeface.BOLD:Typeface.NORMAL);return v;}TextView card(String s,int c){TextView v=tx(s,13,false,Color.WHITE);v.setPadding(dp(10),dp(10),dp(10),dp(10));v.setBackground(bg(c,10));return v;}GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
}
